#!/usr/bin/env node
/**
 * Builds ADE MCP's MCP Apps view into `src/services/remoteMcp/remoteMcpApp/app.generated.ts`
 * from its real sources in the same folder: the TypeScript modules, bundled
 * from `app.ts`, and `app.css`.
 *
 *   node scripts/generate-remote-mcp-app.mjs           # write
 *   node scripts/generate-remote-mcp-app.mjs --check   # exit 1 when the generated file is stale (npm test runs it)
 *
 * Why a generated module and not a text import: the HTML ships inside the
 * brain, which runs as the tsup bundle, from source under `tsx`, and under
 * vitest (the context-budget test serves `tools/list`). Only a plain `.ts`
 * module of strings loads the same way in all three, needs no loader, and
 * keeps `app.ts` under the package's own `tsc --noEmit`. The script is never
 * produced with `Function.prototype.toString`, whose esbuild `__name` helpers
 * do not exist in the host's iframe.
 *
 * esbuild bundles the modules from `app.ts` (anything outside the folder is
 * imported for its types only), minifies, and wraps the script in an IIFE so
 * nothing leaks into the iframe's globals. `--check` compares a hash of every
 * file in the folder but the generated one, recorded in the generated file,
 * so a different esbuild version never fails the check on its own.
 */
import { createHash } from "node:crypto";
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { build, transform } from "esbuild";

const packageRoot = path.dirname(path.dirname(fileURLToPath(import.meta.url)));
const appDir = path.join(packageRoot, "src", "services", "remoteMcp", "remoteMcpApp");
const outputPath = path.join(appDir, "app.generated.ts");
const HASH_LINE = /^\/\/ sources: ([0-9a-f]{64})$/m;

// LF everywhere, so a Windows checkout (autocrlf) hashes the same sources.
const read = (file) => readFileSync(file, "utf8").replace(/\r\n/g, "\n");
const hash = createHash("sha256");
const sourceFiles = readdirSync(appDir).filter((name) => name !== path.basename(outputPath)).sort();
for (const name of sourceFiles) hash.update(name).update("\0").update(read(path.join(appDir, name))).update("\0");
const sourceHash = hash.update(read(fileURLToPath(import.meta.url))).digest("hex");

if (process.argv.includes("--check")) {
  let current = "";
  try { current = readFileSync(outputPath, "utf8"); } catch { /* missing reads as stale */ }
  if (HASH_LINE.exec(current)?.[1] !== sourceHash) {
    console.error(`${path.relative(packageRoot, outputPath)} is stale: run \`npm run mcp-app:build\` in apps/ade-cli and commit the result.`);
    process.exit(1);
  }
  process.exit(0);
}

const bundled = await build({
  entryPoints: [path.join(appDir, "app.ts")],
  bundle: true,
  write: false,
  format: "iife",
  minify: true,
  target: "es2020",
  charset: "utf8",
  legalComments: "none",
  logLevel: "silent",
});
const builtJs = { code: bundled.outputFiles[0].text };
const builtCss = await transform(read(path.join(appDir, "app.css")), { loader: "css", minify: true, charset: "utf8", legalComments: "none" });
for (const [name, text] of [["APP_JS", builtJs.code], ["APP_CSS", builtCss.code]]) {
  // Both are inlined into the HTML; either could end its own element early.
  if (/<\/(script|style)/i.test(text)) throw new Error(`${name} contains a closing script or style tag.`);
}

writeFileSync(outputPath, [
  "// Generated by scripts/generate-remote-mcp-app.mjs from the files in this folder. Do not edit.",
  `// sources: ${sourceHash}`,
  "",
  `export const APP_CSS = ${JSON.stringify(builtCss.code.trim())};`,
  "",
  `export const APP_JS = ${JSON.stringify(builtJs.code.trim())};`,
  "",
].join("\n"));
console.log(`wrote ${path.relative(packageRoot, outputPath)} (js ${Buffer.byteLength(builtJs.code)} B, css ${Buffer.byteLength(builtCss.code)} B)`);
